function getPending(){return data.tasks.filter(v=>!v.done).sort((a,b)=>(a.dueDate||'9999') .localeCompare(b.dueDate||'9999')||(a.dueTime||'').localeCompare(b.dueTime||''));}
function getUpcomingExams(){return data.exams.filter(e=>e.date>=spainToday()).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,50);}
function escapeSubjectOptions(selected='',includeBlank=true){return `${includeBlank?`<option value="">${esc(t('selectSubject'))}</option>`:''}${data.subjects.map(s=>`<option value="${esc(s.id)}" ${s.id===selected?'selected':''}>${esc(s.name)}</option>`).join('')}`;}
function persist(upload=true){data.meta.updatedAt=new Date().toISOString();try{localStorage.setItem(STORAGE_KEY,JSON.stringify(data));}catch(e){console.error('Almacenamiento no disponible',e);toast('No se pudieron guardar los datos','error');}if(upload&&auth&&CLOUD)scheduleCloudSave();}
function applyTheme(){let theme=data.settings.theme;if(theme==='system')theme=matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light';document.body.dataset.theme=theme;document.body.dataset.accent=['blue','lime','coral'].includes(data.settings.accent)?data.settings.accent:'blue';document.documentElement.lang=data.settings.lang;document.querySelector('meta[name="theme-color"]')?.setAttribute('content',theme==='dark'?'#101427':'#f6f7fb');}
function toast(message,type='ok'){const el=document.createElement('div');el.className='toast'+(type==='error'?' error':'');el.innerHTML=icon(type==='error'?'alert':'check')+`<span>${esc(message)}</span>`;document.querySelector('#toast-region').append(el);setTimeout(()=>el.remove(),4300);}
function emptyState(title,desc='',action='',actionName=''){return `<div class="empty-state"><span class="empty-icon">${icon('inbox',26)}</span><strong>${esc(title)}</strong><p>${esc(desc)}</p>${action?`<button class="soft-btn" data-action="${action}">${icon('plus',15)}${esc(actionName)}</button>`:''}</div>`;}
const NAV=[['inicio','home'],['asignaturas','book'],['horario','clock'],['tareas','tasks'],['examenes','graduation'],['calendario','calendar'],['temporizador','target'],['configuracion','settings']];
function setView(view){if(!NAV.some(n=>n[0]===view))return;currentView=view;history.replaceState(null,'','#'+view);closeMenu();render();document.getElementById('main-content')?.focus({preventScroll:true});window.scrollTo({top:0,behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}
function closeMenu(){document.getElementById('sidebar').classList.remove('open');const shade=document.getElementById('mobile-shade');shade.classList.remove('open');shade.hidden=true;}
function render(){applyTheme();renderNav();renderMobileTabs();renderHeader();renderMain();renderRail();renderSync();updateTimeDisplays();}
function renderNav(){document.getElementById('nav-list').innerHTML=NAV.map(([key,ic])=>`<button type="button" data-action="nav" data-view="${key}" class="nav-item ${currentView===key?'active':''}" ${currentView===key?'aria-current="page"':''}>${icon(ic)}<span>${esc(t(key))}</span>${key==='tareas'&&getPending().length?`<span class="nav-number">${getPending().length}</span>`:''}</button>`).join('');document.getElementById('sidebar-focus').innerHTML=`<div class="focus-illustration"><strong>${esc(t('focus'))}</strong>${icon('clock',22)}</div><p>${esc(t('focusSidebar'))}</p><button type="button" data-action="nav" data-view="temporizador">${esc(t('studyNow'))} ${icon('arrow',12)}</button>`;const name=data.settings.name||(auth?.user?.email?.split('@')[0])||t('guest');document.getElementById('profile-button').innerHTML=`<span class="avatar">${esc(name.slice(0,1).toUpperCase())}</span><span class="profile-copy"><strong>${esc(name)}</strong><small>${auth?esc(auth.user?.email||t('accountConnected')):esc(t('guestInfo'))}</small></span>${icon('chevron',15)}`;document.querySelectorAll('[data-i18n]').forEach(el=>{el.textContent=t(el.dataset.i18n);});}
function renderSync(){const el=document.getElementById('sync-status');const online=auth&&CLOUD;el.innerHTML=`<span class="status-dot ${online?(syncState==='syncing'?'pending':'online'):''}"></span>${esc(online?(syncState==='syncing'?t('syncing'):syncState==='error'?t('syncError'):t('connected')):t('local'))}`;}
function renderHeader(){const descriptions={inicio:t('welcomeDesc'),asignaturas:t('allSubjectsDesc'),horario:t('scheduleDesc'),tareas:t('taskManagerDesc'),examenes:t('examPlannerDesc'),calendario:t('calendarDesc'),temporizador:t('focusDesc'),configuracion:t('settingsDesc')};document.getElementById('header-eyebrow').textContent=t('space');document.getElementById('page-title').textContent=t(currentView);document.getElementById('page-subtitle').textContent=descriptions[currentView];document.querySelector('[data-i18n="newTask"]').textContent=t('newTask');document.getElementById('notification-dot').hidden=getPending().filter(x=>x.dueDate&&x.dueDate<=spainToday()).length===0;}
function renderMain(){const views={inicio:renderDashboard,asignaturas:renderSubjects,horario:renderSchedule,tareas:renderTasks,examenes:renderExams,calendario:renderCalendar,temporizador:renderTimer,configuracion:renderSettings};document.getElementById('main-content').innerHTML=views[currentView]();}

